effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  float t = clamp((l - pivot) * contrast + 0.5, 0.0, 1.0);
  vec3 col = mix(colorA.rgb, colorB.rgb, t);
  col = mix(c, col, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
